def gen_methods(methods):
    lines = ["    let methods = HashMap::from(["]
    for m in methods:
        name, subid, is_mut, args_json, idem = m
        if args_json is None:
            args = "empty_args()"
        else:
            args = f'serde_json::json!({args_json})'
        if is_mut:
            lines.append(f'        ("{name}".to_string(), mutation_method("{name}", "{subid}", {args}, None, {"true" if idem else "false"})),')
        else:
            lines.append(f'        ("{name}".to_string(), read_method("{name}", "{subid}", {args}, None)),')
    lines.append("    ]);")
    return "\n".join(lines)

def gen_signals(signals):
    entries = ", ".join([f'signal_decl("{n}", "{s}", state_changed_payload())' for n, s in signals])
    return f"    let signals = vec![{entries}];"

def gen_guarantees(g_str):
    parts = g_str.split(",")
    return f"    let guarantees = PluginCapabilities {{ supports_rollback: {parts[0]}, supports_checkpoints: {parts[1]}, supports_verification: {parts[2]}, atomic_operations: {parts[3]} }};"

# Process each plugin
for pname, (methods, signals, guarantees, ptype) in all_plugins.items():
    func_name = f"{pname}_plugin_schema"

    if ptype == "simple":
        # Check if already has with_caps
        func_pos = content.find(f'pub(crate) fn {func_name}() -> PluginSchema {{')
        if func_pos == -1:
            print(f"SKIP: {pname} not found")
            continue

        # Check if already done
        check_pos = content.find('with_caps(', func_pos)
        func_end = content.find('\n}', func_pos)
        if check_pos != -1 and check_pos < func_end:
            print(f"SKIP: {pname} already has with_caps")
            continue

        # Insert caps before simple_schema and wrap
        simple_pattern = f'pub(crate) fn {func_name}() -> PluginSchema {{\n    simple_schema('
        if simple_pattern not in content:
            print(f"WARN: {pname} simple_schema pattern not found")
            continue

        caps = gen_methods(methods) + "\n" + gen_signals(signals) + "\n" + gen_guarantees(guarantees)
        replacement = f'pub(crate) fn {func_name}() -> PluginSchema {{\n{caps}\n    with_caps(\n        simple_schema('
        content = content.replace(simple_pattern, replacement, 1)

        # Fix closing: find the `    )\n}` after this function
        func_pos = content.find(f'pub(crate) fn {func_name}() -> PluginSchema {{')
        close_pattern = '    )\n}'
        close_pos = content.find(close_pattern, func_pos)
        if close_pos != -1:
            close_repl = '    ),\n        methods,\n        signals,\n        guarantees,\n    )\n}'
            content = content[:close_pos] + close_repl + content[close_pos + len(close_pattern):]
            print(f"OK: {pname} (simple)")
        else:
            print(f"WARN: {pname} closing not found")

    elif ptype == "builder":
        builder_pattern = f'    PluginSchema::builder("{pname}")'
        if builder_pattern not in content:
            print(f"WARN: {pname} builder not found")
            continue

        # Check if already done
        func_pos = content.find(f'pub(crate) fn {func_name}() -> PluginSchema {{')
        check_pos = content.find('with_caps(', func_pos) if func_pos != -1 else -1
        func_end = content.find('\n}', func_pos) if func_pos != -1 else -1
        if check_pos != -1 and check_pos < func_end:
            print(f"SKIP: {pname} already has with_caps")
            continue

        caps = gen_methods(methods) + "\n" + gen_signals(signals) + "\n" + gen_guarantees(guarantees)
        replacement = f'{caps}\n\n    with_caps(\n    PluginSchema::builder("{pname}")'
        content = content.replace(builder_pattern, replacement, 1)

        # Fix .build()
        func_pos = content.find(f'pub(crate) fn {func_name}() -> PluginSchema {{')
        build_pattern = '        .build()\n}'
        build_pos = content.find(build_pattern, func_pos)
        if build_pos != -1:
            build_repl = '        .build(),\n        methods,\n        signals,\n        guarantees,\n    )\n}'
            content = content[:build_pos] + build_repl + content[build_pos + len(build_pattern):]
            print(f"OK: {pname} (builder)")
        else:
            print(f"WARN: {pname} .build() not found")

    elif ptype == "state":
        func_pos = content.find(f'pub(crate) fn {func_name}() -> PluginSchema {{')
        if func_pos == -1:
            print(f"SKIP: {pname} not found")
            continue

        # Check if already done
        check_pos = content.find('with_caps(', func_pos)
        func_end = content.find('\n}', func_pos)
        if check_pos != -1 and check_pos < func_end:
            print(f"SKIP: {pname} already has with_caps")
            continue

        caps = gen_methods(methods) + "\n" + gen_signals(signals) + "\n" + gen_guarantees(guarantees)

        # Special handling for factory (uses builder with state)
        if pname == "factory":
            # Pattern: builder.example(state.clone()).build()
            # Wrap with with_caps
            old_build = "    builder.example(state.clone()).build()\n}"
            new_build = f"""{caps}
    with_caps(
        builder.example(state.clone()).build(),
        methods,
        signals,
        guarantees,
    )
}}"""
            if old_build in content:
                content = content.replace(old_build, new_build, 1)
                print(f"OK: {pname} (factory builder)")
            else:
                print(f"WARN: {pname} factory build pattern not found")
            continue

        # For schema_from_state plugins, we need to wrap the schema_from_state call
        # Insert caps block after the function opening brace
        brace_pos = content.find('{', func_pos)
        insert_pos = brace_pos + 1

        # Check if the function starts with `let state = ...` or directly with `schema_from_state`
        after_brace = content[insert_pos:insert_pos+100].strip()

        if after_brace.startswith('let state') or after_brace.startswith('//'):
            # Multi-line: need to wrap the schema_from_state(...) call
            # Insert caps block and with_caps(
            content = content[:insert_pos] + '\n' + caps + '\n    with_caps(\n        {' + content[insert_pos:]

            # Now find the schema_from_state closing paren and wrap it
            func_pos = content.find(f'pub(crate) fn {func_name}() -> PluginSchema {{')
            sfs_pos = content.find('schema_from_state(', func_pos)

            # Count parens to find matching close
            depth = 0
            i = sfs_pos
            while i < len(content):
                if content[i] == '(':
                    depth += 1
