CLOSE_SIMPLE = '    ),\n        methods,\n        signals,\n        guarantees,\n    )\n}'
CLOSE_BUILDER = '        .build(),\n        methods,\n        signals,\n        guarantees,\n    )\n}'

for pname, methods, signals, guarantees, ptype in plugins:
    fn = f"{pname}_plugin_schema"
    caps = gm(methods) + "\n" + gs(signals) + "\n" + gg(guarantees)

    if ptype == "simple":
        sp = f'pub(crate) fn {fn}() -> PluginSchema {{\n    simple_schema('
        if sp not in content: print(f"WARN: {pname}"); continue
        content = content.replace(sp, f'pub(crate) fn {fn}() -> PluginSchema {{\n{caps}\n    with_caps(\n        simple_schema(', 1)
        fp = content.find(f'pub(crate) fn {fn}() -> PluginSchema {{')
        cp = content.find('    )\n}', fp)
        if cp != -1:
            content = content[:cp] + CLOSE_SIMPLE + content[cp+7:]
            print(f"OK: {pname}")
        else: print(f"WARN: {pname} close")

    elif ptype == "builder":
        bp = f'    PluginSchema::builder("{pname}")'
        if bp not in content: print(f"WARN: {pname} builder"); continue
        content = content.replace(bp, f'{caps}\n\n    with_caps(\n    PluginSchema::builder("{pname}")', 1)
        fp = content.find(f'pub(crate) fn {fn}() -> PluginSchema {{')
        bpos = content.find('        .build()\n}', fp)
        if bpos != -1:
            content = content[:bpos] + CLOSE_BUILDER + content[bpos+15:]
            print(f"OK: {pname}")
        else: print(f"WARN: {pname} build")

    elif ptype == "state":
        fp = content.find(f'pub(crate) fn {fn}() -> PluginSchema {{')
        if fp == -1: print(f"WARN: {pname}"); continue
        brace = content.find('{', fp) + 1
        content = content[:brace] + '\n' + caps + '\n    with_caps(\n        {\n' + content[brace:]
        fp = content.find(f'pub(crate) fn {fn}() -> PluginSchema {{')
        sfs = content.find('schema_from_state(', fp)
        depth = 0
        i = sfs
        while i < len(content):
            if content[i] == '(': depth += 1
            elif content[i] == ')':
                depth -= 1
                if depth == 0:
                    rest = content[i+1:i+5]
                    if rest.startswith('\n}'):
                        content = content[:i] + ')\n        },\n        methods,\n        signals,\n        guarantees,\n    )\n}' + content[i+3:]
                        print(f"OK: {pname}")
                    elif rest.startswith(',\n}'):
                        content = content[:i] + ')\n        },\n        methods,\n        signals,\n        guarantees,\n    )\n}' + content[i+3:]
                        print(f"OK: {pname}")
                    else: print(f"WARN: {pname} close: {repr(rest)}")
                    break
            i += 1

