old = "    builder.example(state.clone()).build()\n}"
new = f"{caps}\n    with_caps(\n        builder.example(state.clone()).build(),\n        methods,\n        signals,\n        guarantees,\n    )\n}}"
if old in content:
    content = content.replace(old, new, 1)
    print("OK: factory")
else: print("WARN: factory")

# cognitive_mcp
fn = "cognitive_mcp_plugin_schema"
caps = gm(cog_m) + "\n" + gs(cog_s) + "\n" + gg(cog_g)
bp = '    PluginSchema::builder("cognitive_mcp")'
if bp in content:
    content = content.replace(bp, f'{caps}\n\n    PluginSchema::builder("cognitive_mcp")', 1)
    fp = content.find(f'pub(crate) fn {fn}() -> PluginSchema {{')
    bpos = content.find('        .build()\n}', fp)
    if bpos != -1:
        subids = ""
        for meth in cog_m: subids += f'        .subid("{meth[0]}", "{meth[1]}")\n'
        for sig in cog_s: subids += f'        .subid("{sig[0]}", "{sig[1]}")\n'
        content = content[:bpos] + f'{subids}        .methods(methods)\n        .signals(signals)\n        .guarantees(guarantees)\n        .build()\n}}' + content[bpos+15:]
        print("OK: cognitive_mcp")
    else: print("WARN: cognitive_mcp build")
else: print("WARN: cognitive_mcp builder")

with open('crates/op-plugins/src/state_plugins/plugin_schema_defs.rs', 'w') as f:
    f.write(content)

